import java.io.BufferedReader
import java.io.InputStreamReader

lateinit var setNums: HashSet<Long>
var n: Long = 0

fun gen(cur: Long, x: Int, y: Int, depth: Int) {
    if (cur > n) return
    if (cur > 0) setNums.add(cur)
    if (depth >= 10) return
    gen(cur * 10 + x, x, y, depth + 1)
    if (y != x) gen(cur * 10 + y, x, y, depth + 1)
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    n = br.readLine().trim().toLong()
    setNums = HashSet()
    for (x in 0..9) {
        for (y in x..9) {
            gen(0L, x, y, 0)
        }
    }
    println(setNums.size)
}
